// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    Roulette c;

    function setUp() public { c = new Roulette{value: 10 ether}(); }

    // fuzzed params: actor (caller) and amount to send
    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        // keep actor non-zero and amount in a wide range including 10 ether
        vm.assume(actor != address(0));
        // bound amount to a reasonable range so vm.deal can work and not overflow
        amount = bound(amount, 0, 100 ether);

        // Ensure actor has funds to send
        vm.deal(actor, amount > 0 ? amount : 1 ether);

        // Make the call as actor to fallback. We cannot call c.fallback(...) directly by name because
        // fallback is a reserved word in source; instead use low-level call from the actor.
        bool ok;
        vm.prank(actor);
        (ok, ) = address(c).call{value: amount}("");

        // General rule (reference): any call that sends exactly 10 ether to C's fallback MUST succeed (not revert).
        // We express this by asserting that when amount == 10 ether the call succeeded.
        // This holds for the reference contract for all inputs, and the mutant (which requires msg.value != 10 ether)
        // will cause such calls to revert for some inputs; the fuzzer will find them.
        if (amount == 10 ether) {
            assertTrue(ok);
        } else {
            // for other amounts we don't require a particular outcome; just assert true trivially
            assertTrue(true);
        }
    }
}
